begin;
-- A45 batch b031, part 1 of 1: 34 videos. Guards: none of them has a row yet; all are videos.
do $g$ begin
  if exists (select 1 from public.media_exercise_sets where media_id in (8019,8020,8021,8023,8024,8025,8026,8029,8033,8034,8035,8037,8038,8041,8042,8043,8045,8046,8047,8048,8049,8050,8051,8052,8053,8054,8057,8058,8059,8060,8061,8062,8063,8064)) then raise exception 'A45 b031/1: rows exist already, nothing written'; end if;
  if (select count(*) from public.media where media_type = 'video' and id in (8019,8020,8021,8023,8024,8025,8026,8029,8033,8034,8035,8037,8038,8041,8042,8043,8045,8046,8047,8048,8049,8050,8051,8052,8053,8054,8057,8058,8059,8060,8061,8062,8063,8064)) <> 34 then raise exception 'A45 b031/1: not all ids are videos, nothing written'; end if;
end $g$;
do $g$ begin
  if (select count(*) from public.media_exercise_sets where media_id in (8019,8020,8021,8023,8024,8025,8026,8029,8033,8034,8035,8037,8038,8041,8042,8043,8045,8046,8047,8048,8049,8050,8051,8052,8053,8054,8057,8058,8059,8060,8061,8062,8063,8064) and jsonb_array_length(taps) = 3 and jsonb_array_length(nouns) between 3 and 4) <> 34 then raise exception 'A45 b031/1: count after the write is wrong, rolled back'; end if;
end $g$;
commit;
